import numpy as np
import math

def feature(values, weights, remaining, capacity, taken):
    """Value-per-sqrt(weight) (a compromise between raw value and density), boosted by a concave bonus for using a larger share of the remaining capacity."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    if v.size == 0:
        return np.zeros(0)
    w_safe = np.maximum(w, 1.0)
    rem = max(float(remaining), 1.0)
    fit = np.sqrt(np.clip(w / rem, 0.0, 1.0))          # in [0, 1]
    score = (v / np.sqrt(w_safe)) * (0.5 + 0.5 * fit)
    scale = float(np.max(np.abs(score)))
    if not math.isfinite(scale) or scale <= 0.0:
        return np.zeros_like(score)
    return score / scale

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """For each candidate: number of other candidates that still fit in the leftover capacity after taking it, divided by k."""
    k = weights.size
    if k == 0:
        return np.zeros(0, dtype=float)
    left = remaining - weights                      # capacity left if this candidate is taken
    fits = weights[None, :] <= left[:, None]        # (k, k): does candidate j fit in candidate i's leftover
    cnt = fits.sum(axis=1) - (weights <= left)      # exclude the candidate itself when it fits its own leftover
    return cnt / max(k, 1)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """For each candidate: fraction of the other candidates it would push out of the knapsack, and the value mass (share of total candidate value) those pushed-out items carry."""
    v = values.astype(np.float64)
    w = weights.astype(np.float64)
    k = v.size
    if k == 0:
        return np.zeros((0, 2))
    rem = float(remaining)
    resid = rem - w                                   # capacity left if this candidate is taken
    blocked = (w[None, :] > resid[:, None]).astype(np.float64)  # things that fit now but not afterwards
    idx = np.arange(k)
    blocked[idx, idx] = 0.0                           # the candidate never blocks itself
    cnt = blocked.mean(axis=1)                        # share of alternatives lost
    tot = v.sum()
    if not np.isfinite(tot) or tot <= 0.0:
        return np.column_stack([cnt, np.zeros(k)])
    mass = (blocked * v[None, :]).sum(axis=1) / tot   # share of pool value lost
    return np.column_stack([cnt, mass])

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """(weights[i] + best partner weight fitting the residue) / remaining, in [0,1]."""
    weights = np.asarray(weights, dtype=float)
    k = weights.shape[0]
    if k == 0 or remaining <= 0:
        return np.zeros(k)
    resid = remaining - weights
    idx = np.arange(k)
    fits = (weights[None, :] <= resid[:, None]) & (idx[None, :] != idx[:, None])
    wj = np.where(fits, weights[None, :], 0.0).max(axis=1)
    return (weights + wj) / float(remaining)

import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """(value - weight) / capacity per candidate, clipped to [-1, 1]."""
    if capacity <= 0:
        return np.zeros_like(values, dtype=float)
    surplus = (values - weights) / float(capacity)
    return np.clip(surplus, -1.0, 1.0)
